commands:
$base = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4D36E972-E325-11CE-BFC1-08002BE10318}'

Get-ChildItem -Path $base -Force -ErrorAction SilentlyContinue |
Where-Object { $_.PSIsContainer -and $_.PSChildName -match '^\d{4}$' } |
ForEach-Object {
  try {
    $p = $_.PSPath
    if ((Get-ItemProperty -Path $p -ErrorAction Stop).PSObject.Properties.Name -contains 'MTU') {
      Set-ItemProperty -Path $p -Name MTU -Type DWord -Value 1500 -Force
    } else {
      New-ItemProperty -Path $p -Name MTU -PropertyType DWord -Value 1500 -Force 
    }
  } catch {}
}

